package com.legbehindneck.fasttrack48.data.knowledge

import androidx.annotation.StringRes
import com.legbehindneck.fasttrack48.R

/**
 * The in-app knowledge base. Card text lives in res/values/strings_knowledge.xml and the cards
 * themselves in [KnowledgeCatalog], both generated by knowledge/export_android.py from the
 * curated set in knowledge/final/. Edit the cards there, never the generated files.
 */
enum class Visibility { Locked, On, Off, FastDays }

/** One category per file in knowledge/final/; [default] is the out-of-the-box visibility. */
enum class KnowledgeCategory(
	val id: String,
	val default: Visibility,
	@StringRes val title: Int,
	@StringRes val subtitle: Int,
) {
	Journey("journey", Visibility.On, R.string.kb_cat_journey, R.string.kb_cat_journey_sub),
	Mind("mind", Visibility.On, R.string.kb_cat_mind, R.string.kb_cat_mind_sub),
	Food("food", Visibility.On, R.string.kb_cat_food, R.string.kb_cat_food_sub),
	Rhythm("rhythm", Visibility.On, R.string.kb_cat_rhythm, R.string.kb_cat_rhythm_sub),
	Comfort("comfort", Visibility.On, R.string.kb_cat_comfort, R.string.kb_cat_comfort_sub),
	Women("women", Visibility.Off, R.string.kb_cat_women, R.string.kb_cat_women_sub),
	Medical("medical", Visibility.Off, R.string.kb_cat_medical, R.string.kb_cat_medical_sub),
	Traditions("traditions", Visibility.FastDays, R.string.kb_cat_traditions, R.string.kb_cat_traditions_sub),
	Essentials("essentials", Visibility.Locked, R.string.kb_cat_essentials, R.string.kb_cat_essentials_sub);

	/** A user toggle exists only for On/Off categories. */
	val toggleable: Boolean get() = default == Visibility.On || default == Visibility.Off
}

enum class ConditionGroup(@StringRes val title: Int) {
	BloodSugar(R.string.kb_cond_group_sugar),
	HeartKidneys(R.string.kb_cond_group_heart),
	Hormones(R.string.kb_cond_group_hormones),
	Medicines(R.string.kb_cond_group_meds),
	Other(R.string.kb_cond_group_other),
}

/** Health-profile chips. A medical card shows only when one of its conditions is selected. */
enum class HealthCondition(val id: String, val group: ConditionGroup, @StringRes val label: Int) {
	T2d("t2d", ConditionGroup.BloodSugar, R.string.kb_cond_t2d),
	DiabetesMeds("diabetes-meds", ConditionGroup.BloodSugar, R.string.kb_cond_diabetes_meds),
	T1("t1", ConditionGroup.BloodSugar, R.string.kb_cond_t1),
	BpHeart("bp-heart", ConditionGroup.HeartKidneys, R.string.kb_cond_bp_heart),
	Kidney("kidney", ConditionGroup.HeartKidneys, R.string.kb_cond_kidney),
	GoutStones("gout-stones", ConditionGroup.HeartKidneys, R.string.kb_cond_gout_stones),
	Thyroid("thyroid", ConditionGroup.Hormones, R.string.kb_cond_thyroid),
	Pcos("pcos", ConditionGroup.Hormones, R.string.kb_cond_pcos),
	Glp1("glp1", ConditionGroup.Medicines, R.string.kb_cond_glp1),
	Steroids("steroids", ConditionGroup.Medicines, R.string.kb_cond_steroids),
	Lithium("lithium", ConditionGroup.Medicines, R.string.kb_cond_lithium),
	Warfarin("warfarin", ConditionGroup.Medicines, R.string.kb_cond_warfarin),
	DailyMeds("daily-meds", ConditionGroup.Medicines, R.string.kb_cond_daily_meds),
	Cancer("cancer", ConditionGroup.Other, R.string.kb_cond_cancer),
	Gallbladder("gallbladder", ConditionGroup.Other, R.string.kb_cond_gallbladder);

	companion object {
		fun fromId(id: String): HealthCondition? = entries.firstOrNull { it.id == id }
	}
}

/** Evidence grade; A strongest. The label is the quiet, user-facing name for it. */
enum class Grade(@StringRes val label: Int) {
	A(R.string.kb_label_a), B(R.string.kb_label_b), C(R.string.kb_label_c), D(R.string.kb_label_d)
}

/** Declared in order of increasing weight, so [ordinal] ranks them. */
enum class Safety { None, Caution, Stop }

/** Context in which an essentials card is surfaced (see INTEGRATION.md §3F). */
enum class Gate { Onboarding, Age65, Female }

/**
 * One knowledge card. String fields are resource ids; 0 means absent (only [action] and
 * [caveat] can be absent). [stages] are dial stage indices (FastingJourney.stages).
 */
data class KnowledgeCard(
	val id: String,
	val category: KnowledgeCategory,
	@StringRes val title: Int,
	@StringRes val claim: Int,
	@StringRes val why: Int,
	@StringRes val action: Int,
	@StringRes val caveat: Int,
	val grade: Grade,
	val safety: Safety,
	val stages: Set<Int>,
	val events: Set<String>,
	val symptoms: Set<String>,
	val conditions: Set<HealthCondition>,
	val gate: Gate?,
	val sources: List<String>,
)

/** Bibliography groups on Sources & credits, in display order. */
enum class ReferenceKind { Book, Study, Talk }

/**
 * One cited work, from knowledge/references.json via [KnowledgeReferences]. [text] is the full
 * citation, never translated; [url] is empty when there is no stable link (most books).
 */
data class KnowledgeReference(val kind: ReferenceKind, val text: String, val url: String)
